package dev.kopybook;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import dev.kopybook.codec.DecodeOptions;
import dev.kopybook.copybook.CopybookParser;
import dev.kopybook.copybook.Node;

import java.io.IOException;
import java.math.BigDecimal;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.*;

/** Access to the shared golden corpus (generated by corpus/generator/gen_corpus.py). */
final class Corpus {
    static final ObjectMapper M = new ObjectMapper();
    static final Path DIR = Path.of(System.getProperty("kopybook.corpus", "../corpus"));

    record Case(String name, Node root, String codepage, String framing, int recordLength,
                List<byte[]> records, List<JsonNode> expected, Path copybook, String record) {
        DecodeOptions options() { return new DecodeOptions().codepage(codepage); }
    }

    static List<JsonNode> manifest() throws IOException {
        List<JsonNode> out = new ArrayList<>();
        M.readTree(DIR.resolve("manifest.json").toFile()).get("cases").forEach(out::add);
        return out;
    }

    static Case load(JsonNode c) throws IOException {
        String name = c.get("case").asText();
        Path cb = DIR.resolve(c.get("copybook").asText());
        Node root = CopybookParser.parse(cb, CopybookParser.Format.AUTO, c.has("copyPath") ? List.of(DIR.resolve(c.get("copyPath").asText())) : List.of()).record(c.get("record").asText());
        byte[] data = Files.readAllBytes(DIR.resolve("data").resolve(name + ".bin"));
        String framing = c.get("framing").asText();
        int len = c.get("recordLength").asInt();
        List<byte[]> recs = new ArrayList<>();
        if (framing.equals("rdw")) {
            int i = 0;
            while (i < data.length) {
                int n = ((data[i] & 0xFF) << 8) | (data[i + 1] & 0xFF);
                recs.add(Arrays.copyOfRange(data, i + 4, i + n));
                i += n;
            }
        } else {
            for (int i = 0; i < data.length; i += len) recs.add(Arrays.copyOfRange(data, i, i + len));
        }
        List<JsonNode> exp = new ArrayList<>();
        for (String l : Files.readAllLines(DIR.resolve("expected").resolve(name + ".jsonl"), StandardCharsets.UTF_8))
            if (!l.isBlank()) exp.add(M.readTree(l));
        return new Case(name, root, c.get("codepage").asText(), framing, len, recs, exp, cb, c.get("record").asText());
    }

    /** Java values -> JSON in the same canonical form as the Python golden files. */
    static JsonNode json(Object v) throws IOException {
        return M.readTree(M.writeValueAsString(canon(v)));
    }

    @SuppressWarnings("unchecked")
    static Object canon(Object v) {
        if (v instanceof BigDecimal d) return d.toPlainString();
        if (v instanceof Map<?, ?> m) {
            Map<String, Object> out = new LinkedHashMap<>();
            m.forEach((k, x) -> out.put((String) k, canon(x)));
            return out;
        }
        if (v instanceof List<?> l) {
            List<Object> out = new ArrayList<>();
            for (Object x : l) out.add(canon(x));
            return out;
        }
        return v;
    }
}
